const {Meta:M,RANKS,ACHIEVEMENTS,CLASS_META,WORLD,SKINS,STARTERS,MELEE,rollBuff,rollGunMod,rollMelee,rankXp}=__meta; const g=__dmh, D=g.data, out={};
M.setUnlockAll(false);
// 1. every name a reward refers to exists
const bad=[]; const U=(n)=>D.upgrades.find(u=>u.name===n), W=(n)=>D.weapons.find(w=>w.name===n);
const chk=(R,src)=>{ (R.upgrades||[]).forEach(n=>{if(!U(n))bad.push(src+':up:'+n)}); (R.guns||[]).forEach(n=>{if(!W(n))bad.push(src+':gun:'+n)}); (R.blades||[]).forEach(n=>{if(!MELEE.find(m=>m.name===n))bad.push(src+':blade:'+n)}); if(R.skin&&!SKINS.find(s=>s.id===R.skin))bad.push(src+':skin:'+R.skin); if(R.starter&&!W(R.starter))bad.push(src+':starter:'+R.starter); };
RANKS.forEach((R,i)=>chk(R,'rank'+(i+1))); ACHIEVEMENTS.forEach(A=>chk(A,A.id)); CLASS_META.forEach(C=>C.rewards.forEach((R,k)=>{chk(R,C.id+k); (R.upgrades||[]).forEach(n=>{const u=U(n); if(u&&u.cls!==C.id)bad.push('wrongclass:'+n+':'+u.cls)})}));
WORLD.forEach(m=>{const u=U(m.heirloom); if(!u||u.rarity!=='Common')bad.push('heir:'+m.heirloom); if(!g.constructor) 0;});
// no reward is handed out twice, and every skin but the first has a source
const seen={}; const dup=[]; const all=[...RANKS,...ACHIEVEMENTS,...CLASS_META.flatMap(C=>C.rewards)]; all.forEach(R=>[...(R.upgrades||[]),...(R.guns||[]),...(R.blades||[]),...(R.skin?['skin:'+R.skin]:[]),...(R.starter?['st:'+R.starter]:[])].forEach(n=>{if(seen[n])dup.push(n);seen[n]=1}));
const noSrc=SKINS.filter(s=>s.id!=='drifter'&&!seen['skin:'+s.id]).map(s=>s.id);
out.bad=bad; out.dup=dup; out.noSrc=noSrc; out.ids=ACHIEVEMENTS.length+' ch, dupIds '+(new Set(ACHIEVEMENTS.map(a=>a.id)).size!==ACHIEVEMENTS.length);
out.xpTable=[2,5,10,15,20].map(r=>r+':'+rankXp(r)).join(' ');
// 2. a fresh save: what is locked
const lk=()=>({rank:M.rank(),thunder:M.gunLocked('Thunderhead'),td:M.upgradeLocked('Time Dilator'),twin:M.upgradeLocked('Twin Link'),kat:M.bladeLocked('Gunslinger Katana'),back:M.starterUnlocked('Back-Alley'),heir:M.heirloomUnlocked('wharf'),rec:M.upgradeLocked('Recycler'),mask:M.upgradeLocked("Hangman's Mask"),unb:M.upgradeLocked('Unbroken'),van:M.upgradeLocked('Vanguard'),skinL:M.skinUnlocked('legend'),lockedUps:D.upgrades.filter(u=>M.upgradeLocked(u.name)).length,lockedGuns:D.weapons.filter(w=>M.gunLocked(w.name)).length});
out.fresh=lk();
// 3. rolls never hand out a locked thing; every tier still has something for every class
let viol=0, empty=[]; for(const cls of ['gunslinger','brawler','engineer','sniper','bomber']){ for(let t=0;t<5;t++){ const cnt={}; for(let i=0;i<400;i++){ const u=rollBuff(t,new Array(D.upgrades.length).fill(0),cls); if(u<0){empty.push(cls+t);break;} if(M.upgradeLocked(D.upgrades[u].name))viol++; cnt[u]=1; } if(t===4) out['leg_'+cls]=Object.keys(cnt).map(i=>D.upgrades[i].name).join('/'); } for(let i=0;i<400;i++){ const u=rollGunMod([],D.weapons[8],cls,0); if(u>=0&&M.upgradeLocked(D.upgrades[u].name))viol++; } }
for(let i=0;i<300;i++){ for(let r=1;r<5;r++){ const m=rollMelee(r,0); if(M.bladeLocked(MELEE[m].name))viol++; } }
out.viol=viol; out.empty=empty;
// 4. earn things
M.popEvents(); M.beginRun();
M.roundStarted(4,'wharf'); const e1=M.popEvents().map(e=>e.toast||e.banner);
for(let r=1;r<=8;r++) M.roundCleared(r,'wharf','bomber',0); const e2=M.popEvents().map(e=>e.banner+' / '+e.toast);
M.bossKilled(false,2); M.bossKilled(true,2); M.won('wharf',2); const e3=M.popEvents().map(e=>e.banner+' / '+e.toast);
out.e1=e1; out.e2=e2; out.e3=e3; out.after=lk(); out.sum=M.runSummary(); out.medal=M.medal('wharf'); out.how=[M.howToUnlock('guns','Thunderhead'),M.howToUnlock('skin','m_bomber'),M.howToUnlock('upgrades','Twin Link'),M.howToUnlock('blades',"Gravedigger's Shovel")];
M.setHeirloom('wharf'); out.heirSel=M.heirloom(); M.setHeirloom('mine'); out.heirStill=M.heirloom();
JSON.stringify(out,null,1)
